Here's a simple command-line rock, paper, scissors game:

```python
import random

CHOICES = ["rock", "paper", "scissors"]
BEATS = {"rock": "scissors", "paper": "rock", "scissors": "paper"}

def get_player_choice():
    while True:
        choice = input("Choose rock, paper, or scissors (or 'q' to quit): ").strip().lower()
        if choice in CHOICES or choice == "q":
            return choice
        print("Invalid choice, try again.")

def decide_winner(player, computer):
    if player == computer:
        return "tie"
    return "player" if BEATS[player] == computer else "computer"

def main():
    scores = {"player": 0, "computer": 0, "tie": 0}
    print("Welcome to Rock, Paper, Scissors!")

    while True:
        player = get_player_choice()
        if player == "q":
            break

        computer = random.choice(CHOICES)
        print(f"You chose {player}, computer chose {computer}.")

        result = decide_winner(player, computer)
        scores[result] += 1

        if result == "tie":
            print("It's a tie!")
        elif result == "player":
            print("You win this round!")
        else:
            print("Computer wins this round!")

        print(f"Score -> You: {scores['player']} | Computer: {scores['computer']} | Ties: {scores['tie']}\n")

    print("Thanks for playing!")

if __name__ == "__main__":
    main()
```

Save it as rps.py and run it with python rps.py. The BEATS dictionary keeps the win logic compact: each choice maps to the one it defeats, so checking for a winner is a single lookup.

